/**
 * 获取当前时间减去指定小时后的时间戳（到秒）
 * @param hoursToSubtract 要减去的小时数
 * @returns 时间戳（秒）
 */
export function getTimestampMinusHours(hoursToSubtract: number = 4): number {
  // 获取当前时间（毫秒）
  const now = new Date().getTime()

  // 计算4小时的毫秒数
  const fourHoursInMs = hoursToSubtract * 60 * 60 * 1000

  // 计算减去4小时后的时间（毫秒）
  const timeMinusFourHours = now - fourHoursInMs

  // 转换为秒并取整
  return Math.floor(timeMinusFourHours / 1000)
}

// 距离时间（缩写版）
export function getTimeDifferenceAbbr(timestamp: number) {
  // 当前时间戳（毫秒）
  const now = Date.now()

  // 计算差值（毫秒）
  const diffMs = now - timestamp

  // 转换为秒
  const diffSeconds = Math.floor(diffMs / 1000)

  // 计算各个时间单位
  const seconds = diffSeconds % 60
  const minutes = Math.floor(diffSeconds / 60) % 60
  const hours = Math.floor(diffSeconds / 3600) % 24
  const days = Math.floor(diffSeconds / 86400) % 30 // 每月按30天计算
  const months = Math.floor(diffSeconds / (86400 * 30)) % 12
  const years = Math.floor(diffSeconds / (86400 * 365))

  // 构建结果字符串
  let result = ''

  if (years > 0) {
    result += `${years}y `
    // return `${years}y`
  }

  if (months > 0) {
    if (result) {
      return result + `${months}mo `
    }
    result += `${months}mo `
  }

  if (days > 0) {
    if (result) {
      return result + `${days}d `
    }
    result += `${days}d `
    // return `${days}d`
  }

  if (hours > 0) {
    if (result) {
      return result + `${hours}h `
    }
    result += `${hours}h `
    // return `${hours}h`
  }

  if (minutes > 0) {
    if (result) {
      return result + `${minutes}m `
    }
    result += `${minutes}m `
    // return `${minutes}m`
  }

  if (seconds > 0) {
    result += `${seconds}s `
    // return `${seconds}s`
  }

  // 如果结果为空（时间戳在未来），返回"刚刚"
  if (result === '') {
    return '0s '
  }
  // console.log('🚀 ~ getTimeDifferenceAbbr ~ result:', result)

  return result + 'ago'
}
