import useGetApiData from '@/hooks/pro/useGetApiData'
import useProStore from '@/store/pro'
import { toLongCoinType } from '@/utils/contract-helper'
import { SelectTab, useTokenSelect } from '@cetus/design'
import SingleTokenInfo from '@cetus/design/src/components/common/SingleTokenInfo'
import { useDebounceFunction } from '@cetus/hooks'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { Token } from '@cetus/types'
import { NoData, SearchInput } from '@cetus/ui-kit'
import Icon from '@cetus/ui-kit/src/components/Icon'
import { Box, Center, HStack, Popover, PopoverBody, PopoverContent, PopoverTrigger, Text, useDisclosure, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useRef, useState } from 'react'
import FilterTable from './FilterTable'

interface TokenDropSelectProps {
  onCoinSelect: (item: any) => void
  whiteTokenList?: any
  selectCoin?: any
}
const tabList = [
  {
    label: 'Watchlist',
    value: 'watchlist'
  },
  {
    label: '24H Volume',
    value: 'volume24h'
  },
  {
    label: 'Top Gainers',
    value: 'topGainers'
  }
]
export default function TokenDropSelectBlock({ selectCoin, whiteTokenList, onCoinSelect }: TokenDropSelectProps) {
  const { showTokenInfo } = useProStore()
  const { isApp } = useWindowWidth()
  const firstItemRef = useRef(null)
  const popoverRef = useRef<HTMLDivElement>(null)
  const { isOpen, onOpen, onClose } = useDisclosure()
  const [currentTab, setCurrentTab] = useState('24H Volume')

  const [isLoading, setIsLoading] = useState(true)

  const { recentSearchTokens, proTokenMap, setClearRecentSearchTokens, setRecentSearchTokens, proTokenList, proTokenListLoading, proTokenStatsMap } =
    useProStore()

  const { getProTokenList, searchProToken } = useGetApiData()
  const [inputValue, setInputValue] = useState('')
  const { getUserCollectList } = useTokenSelect()
  const [tokenList, setTokenList] = useState<any>()
  const { userCollectList } = useTokenSelectStore()
  const handleClose = () => {
    setInputValue('')
    setCurrentTab('24H Volume')
    getProTokenList('vol_24')
    setTokenList([])
    onClose()
  }

  const collectList = useMemo(() => {
    return userCollectList?.map((item: any) => {
      const statsInfo = proTokenStatsMap?.get(toLongCoinType(item?.coin_type) as any)
      if (statsInfo) {
        return {
          ...item,
          ...statsInfo
        }
      }
      return item
    })
  }, [userCollectList, proTokenStatsMap])

  // 监听全局点击，关闭 Popover
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (isOpen && popoverRef.current && !popoverRef.current.contains(e.target as Node)) {
        // onClose()
        handleClose()
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [isOpen, onClose])

  const handleInputChange = (value: string) => {
    const regValue = value.replace(/[^[a-zA-Z0-9\s]+$/g, '')
    setInputValue(regValue)
    if (regValue) {
      setIsLoading(true)
      debouncedFilter(regValue)
    } else {
      if (currentTab === 'Watchlist') {
        setTokenList(collectList)
      } else {
        setTokenList(proTokenList.slice(0, 20))
      }
    }
  }

  const debouncedFilter = useDebounceFunction(async (value: string) => {
    const result = await searchProToken(value)
    console.log('🚀 ~ debouncedFilter ~ result:', result)
    setTokenList(result)
    setIsLoading(false)
  }, 500)

  const handleCurrentTab = (label: string) => {
    setIsLoading(true)
    setCurrentTab(label)
    if (label == 'Watchlist') {
      getUserCollectList()
    } else {
      getProTokenList(label == 'Top Gainers' ? 'change_percentage' : 'vol_24')
    }
  }

  useEffect(() => {
    if (currentTab == 'Watchlist') {
      setTokenList(collectList)
      setIsLoading(false)
    } else {
      if (!proTokenListLoading) {
        setTokenList(proTokenList.slice(0, 20))
        setIsLoading(false)
      }
    }
  }, [collectList, proTokenList, proTokenListLoading])

  const [hoverIconIndex, setHoverIconIndex] = useState(-1)
  return (
    <div ref={popoverRef}>
      <Popover
        isLazy
        placement="bottom-end"
        modifiers={[
          {
            name: 'flip',
            enabled: false // Disable automatic flip
          },
          {
            name: 'shift',
            enabled: false // Disable automatic shift
          }
        ]}
        initialFocusRef={firstItemRef}
        isOpen={isOpen}
        trigger="click"
        // onClose={onClose}
        onClose={handleClose}
        onOpen={onOpen}
      >
        <PopoverTrigger>
          <Center ref={firstItemRef} as="button" onClick={() => onOpen()}>
            <HStack>
              <SingleTokenInfo
                haveTooltip={true}
                imgBoxStyle={{ w: '32px', h: '32px' }}
                symbolFontSize="16px"
                nameEllipsesDecimals={20}
                coinType={showTokenInfo?.coin_type}
                warningIcon={{ iconW: '16px', iconH: '16px' }}
              />
              <Icon
                svgW="16px"
                xlinkHref="#icon-icon_arrow"
                variant="gray"
                transition="transform 0.5s"
                transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
              />
            </HStack>
          </Center>
        </PopoverTrigger>
        {isOpen && (
          <PopoverContent
            ml={{ base: '12px', lg: '20px' }}
            w={{
              base: 'calc(100vw - 24px)',
              lg: '340px'
            }}
          >
            <PopoverBody p="0px">
              <VStack align="flex-start" w="100%" p="8px" borderRadius="12px">
                <Box
                  w="100%"
                  // mb="8px"
                  sx={{
                    input: {
                      borderRadius: '8px',
                      fontSize: '14px'
                    }
                  }}
                >
                  <SearchInput placeholder="Search tokens" searchText={inputValue} onChange={(value: string) => handleInputChange(value)} />
                </Box>
                {recentSearchTokens && recentSearchTokens?.length > 0 && (
                  <VStack w="100%" align="flex-start" gap="8px">
                    <HStack w="100%" justify="space-between">
                      <Text fontSize="12px" color="text_caption" m="4px 0">
                        Recent Searches
                      </Text>
                      <Text _hover={{ color: 'text_caption' }} fontSize="12px" cursor="pointer" onClick={() => setClearRecentSearchTokens()}>
                        Clear all
                      </Text>
                    </HStack>
                    <HStack gap="8px" flexWrap="wrap">
                      {recentSearchTokens?.toReversed()?.map((token: Token, index) => {
                        return (
                          <HStack
                            key={token.coin_type}
                            w="auto"
                            p={{ base: '6px 8px', lg: '6px 12px' }}
                            align="center"
                            borderRadius="8px"
                            background="bg_secondary"
                            borderStyle="solid"
                            border="1px"
                            borderColor="border"
                            cursor="pointer"
                            position="relative"
                            userSelect="none"
                            _hover={{
                              background: 'primary_opacity.10'
                            }}
                            onClick={() => {
                              onCoinSelect(token)
                              handleClose()
                            }}
                            onMouseEnter={() => setHoverIconIndex(index)}
                            onMouseLeave={() => setHoverIconIndex(-1)}
                          >
                            <SingleTokenInfo
                              token={token}
                              imgBoxStyle={{ w: '20px', h: '20px' }}
                              symbolFontSize="14px"
                              haveName={false}
                              warningIcon={{ iconW: '10px', iconH: '10px' }}
                            />
                            {hoverIconIndex == index ? (
                              <Icon
                                xlinkHref="#icon-icon_close"
                                variant="round"
                                position="absolute"
                                boxW="20px"
                                boxH="20px"
                                top="-8px"
                                right="-8px"
                                onClick={e => {
                                  e.stopPropagation()
                                  setRecentSearchTokens(token, true)
                                }}
                              />
                            ) : null}
                          </HStack>
                        )
                      })}
                    </HStack>
                  </VStack>
                )}
                {!inputValue && (
                  <SelectTab
                    type="outlineTab"
                    wrapStyle={{
                      w: {
                        base: '100%'
                      },
                      gap: '0',
                      borderRadius: '8px',
                      p: '4px'
                    }}
                    itemStyle={{
                      w: 'calc(100% / 3)',
                      fontSize: '12px',
                      h: '28px',
                      p: '8px 0px'
                    }}
                    tabList={tabList}
                    currentTab={currentTab}
                    handleChangeTab={item => handleCurrentTab(item.label)}
                  />
                )}
                {tokenList?.length == 0 && !isLoading ? (
                  <Center w="100%" sx={{ p: { color: 'primary_gray', fontSize: '12px' } }}>
                    <NoData type="nodata" p="12px" text={currentTab == 'Watchlist' ? 'No tokens in your watchlist.' : 'No Data'} noBorder />
                  </Center>
                ) : (
                  <Box w="100%" maxH="310px" overflow="auto">
                    <FilterTable
                      isLoading={isLoading}
                      data={tokenList}
                      onRowClick={(item: any) => {
                        const tokenInfo = item?.coin_type ? item : proTokenMap?.get(item?.coinType)
                        onCoinSelect({ ...item, ...tokenInfo })
                        setRecentSearchTokens({ ...item, ...tokenInfo })
                        // onClose()
                        handleClose()
                      }}
                    />
                  </Box>
                )}
              </VStack>
            </PopoverBody>
          </PopoverContent>
        )}
      </Popover>
    </div>
  )
}
